// ---- edit these once after import ----
const CONFIG = {
  model: 'anthropic/claude-sonnet-5',            // any OpenRouter model id
  fallbackModels: ['anthropic/claude-sonnet-4.6'], // OpenRouter tries these if the first is down
  telegramChatId: 'YOUR_TELEGRAM_CHAT_ID',
};

// Payload = KPI snapshot assembled from Redshift by the kpi-snapshot Lambda (aggregates only, no PII).
const snap = $json.body || $json;
const system = [
  'You are a senior payments analyst for an Indian event-ticketing platform.',
  'You get an hourly KPI snapshot (INR) with the previous window for comparison.',
  'Write for an ops/finance audience. Use ONLY numbers present in the snapshot; do not estimate or invent figures.',
  'If attempts < 50, say volume is too low for firm conclusions.',
  'Reply ONLY with JSON: {"headline": string, "health": "green"|"amber"|"red",',
  ' "key_findings": [3-5 strings], "anomalies": [strings], "recommended_actions": [up to 3 strings],',
  ' "watch_next_hour": string}.',
  'Health: red if success rate < 85% or a gateway < 75%; amber if success rate dropped > 3 pts vs previous window; else green.'
].join(' ');
return [{ json: { snapshot: snap, config: CONFIG, body: {
  model: CONFIG.model,
  models: [CONFIG.model, ...CONFIG.fallbackModels],
  temperature: 0.3,
  max_tokens: 900,
  response_format: { type: 'json_object' },
  messages: [ { role: 'system', content: system }, { role: 'user', content: JSON.stringify(snap) } ],
} } }];

// Parse the LLM answer and run a groundedness check: every number the model quotes must
// exist in the snapshot (±0.5 or ±1%), otherwise it is flagged as unverified.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const prev = $('Build prompt').first().json;
const snap = prev.snapshot;
const content = $json.choices?.[0]?.message?.content;

const known = [];
(function walk(v) {
  if (typeof v === 'number') known.push(v);
  else if (Array.isArray(v)) v.forEach(walk);
  else if (v && typeof v === 'object') Object.values(v).forEach(walk);
})(snap);
const isKnown = n => known.some(k => Math.abs(k - n) <= Math.max(0.5, Math.abs(k) * 0.01))
  || n === 1 || n === 2 || n === 3 || n === snap.lookback_minutes;

let r, parseError = null;
try { r = JSON.parse(content); } catch (e) { parseError = content ? 'invalid JSON from model' : 'no response from model'; }

if (!r) {
  const t = snap.totals || {};
  const text = `📊 <b>TicketPulse payments - last ${snap.lookback_minutes} min</b>\n` +
    `Success rate ${t.success_rate_pct ?? '-'}% on ${t.attempts ?? 0} attempts · captured ₹${Math.round(t.captured_inr || 0).toLocaleString('en-IN')}\n` +
    `(LLM insights unavailable: ${esc(parseError)})`;
  return [{ json: { chat_id: prev.config.telegramChatId, text, silent: true } }];
}

const allText = [r.headline, ...(r.key_findings || []), ...(r.anomalies || []), ...(r.recommended_actions || []), r.watch_next_hour].join(' ');
const quoted = (allText.match(/-?\d[\d,]*\.?\d*/g) || []).map(s => parseFloat(s.replace(/,/g, ''))).filter(n => !isNaN(n));
const unverified = [...new Set(quoted.filter(n => !isKnown(n)))];

const icon = { green: '🟢', amber: '🟠', red: '🔴' }[r.health] || '⚪';
let text = `${icon} <b>${esc(r.headline)}</b>\n<i>${esc(snap.window_start)} → ${esc(snap.window_end)}</i>\n\n`;
for (const f of r.key_findings || []) text += `• ${esc(f)}\n`;
if ((r.anomalies || []).length) { text += `\n<b>Anomalies</b>\n`; for (const a of r.anomalies) text += `⚠️ ${esc(a)}\n`; }
if ((r.recommended_actions || []).length) { text += `\n<b>Actions</b>\n`; for (const a of r.recommended_actions) text += `→ ${esc(a)}\n`; }
if (r.watch_next_hour) text += `\n👀 ${esc(r.watch_next_hour)}\n`;
if (unverified.length) text += `\n<i>Unverified numbers in LLM output: ${unverified.slice(0, 6).join(', ')}</i>`;
return [{ json: { chat_id: prev.config.telegramChatId, text, silent: r.health === 'green',
                  health: r.health, insights: r, unverified_numbers: unverified } }];
